/**
 * EN/FR i18n core. English source strings are the keys (gettext style); fr.json is generated by
 * scripts/i18n (extract → LibreTranslate → glossary). Templates use {0}, {1} for dynamic parts.
 * The locale lives in the `pc_locale` cookie; English is the default and the server render.
 */
import fr from "./fr.json";

export type Locale = "en" | "fr";
export const LOCALE_COOKIE = "pc_locale";

let current: Locale = "en";
export const getLocale = (): Locale => current;
export function setLocale(l: Locale) {
  current = l;
}

const dict = fr as Record<string, string>;
const cache = new Map<string, string>();
const esc = (s: string) => s.replace(/[.*+?^$()|[\]\\]/g, "\\$&");
type Pattern = { re: RegExp; slots: number[]; fr: string };
let patterns: Pattern[] | null = null;
function compile(): Pattern[] {
  return Object.keys(dict)
    .filter((k) => /\{\d+\}/.test(k))
    .map((k) => {
      const slots: number[] = [];
      const src = esc(k).replace(/\\?\{(\d+)\\?\}/g, (_m, n) => {
        slots.push(Number(n));
        return "(.+?)";
      });
      return { re: new RegExp(`^${src}$`), slots, fr: dict[k] };
    })
    .sort((a, b) => b.re.source.length - a.re.source.length);
}

/** Translate one rendered string (keeps surrounding whitespace). No-op in English. */
export function tr(s: string, locale: Locale = current): string {
  if (locale === "en" || !s || !/[A-Za-z]/.test(s)) return s;
  const hit = cache.get(s);
  if (hit !== undefined) return hit;
  const key = s.replace(/\s+/g, " ").trim();
  let t = dict[key];
  if (t === undefined) {
    patterns ??= compile();
    for (const p of patterns) {
      const m = p.re.exec(key);
      if (m) {
        t = p.fr.replace(/\{(\d+)\}/g, (_x, n) => m[p.slots.indexOf(Number(n)) + 1] ?? "");
        break;
      }
    }
  }
  const lead = s.match(/^\s*/)?.[0] ?? "";
  const tail = s.match(/\s*$/)?.[0] ?? "";
  const out = t === undefined ? s : lead + t + tail;
  cache.set(s, out);
  return out;
}

export function readLocaleCookie(cookie: string): Locale {
  const m = cookie.match(/(?:^|;\s*)pc_locale=(en|fr)/);
  return (m?.[1] as Locale) ?? "en";
}

/** Persist the choice (1 year) and reload so every screen renders in the new language. */
export function chooseLocale(l: Locale) {
  document.cookie = `${LOCALE_COOKIE}=${l}; path=/; max-age=31536000; samesite=lax`;
  window.location.reload();
}
